package com.reqlens.app;

import android.app.*;import android.content.*;import android.graphics.Typeface;import android.os.Bundle;import android.view.*;import android.widget.*;import java.net.URL;import java.util.*;

public final class ProxyHistoryActivity extends Activity {
 private final ArrayList<ProxyEvent> items=new ArrayList<>(); private ArrayAdapter<ProxyEvent> adapter; private EditText filter; private Spinner source,status; private TextView summary;
 @Override public void onCreate(Bundle b){super.onCreate(b);ProjectRepository.init(this);ProxyHistoryRepository.init(this);setContentView(ui());refresh();}
 private View ui(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Proxy History");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);TextView n=new TextView(this);n.setText("Browser, Repeater, Variations and VPN metadata in one timeline. Encrypted app traffic remains metadata-only.");r.addView(n);summary=new TextView(this);summary.setPadding(0,6,0,6);r.addView(summary);LinearLayout row=new LinearLayout(this);filter=new EditText(this);filter.setHint("host / app / protocol / URL / SNI");row.addView(filter,new LinearLayout.LayoutParams(0,48,1));Button f=new Button(this);f.setText("FILTER");f.setOnClickListener(v->refresh());row.addView(f,new LinearLayout.LayoutParams(100,48));r.addView(row);LinearLayout opts=new LinearLayout(this);source=new Spinner(this);source.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"ALL SOURCES","browser","repeater","variations","capture"}));source.setOnItemSelectedListener(sel());opts.addView(source,new LinearLayout.LayoutParams(0,48,1));status=new Spinner(this);status.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"ALL STATUS","2xx","3xx","4xx","5xx","ERROR"}));status.setOnItemSelectedListener(sel());opts.addView(status,new LinearLayout.LayoutParams(0,48,1));r.addView(opts);LinearLayout presetRow=new LinearLayout(this);Button savePreset=new Button(this);savePreset.setText("SAVE FILTER");savePreset.setOnClickListener(v->saveFilterPreset());presetRow.addView(savePreset,new LinearLayout.LayoutParams(0,44,1));Button loadPreset=new Button(this);loadPreset.setText("LOAD FILTER");loadPreset.setOnClickListener(v->loadFilterPreset());presetRow.addView(loadPreset,new LinearLayout.LayoutParams(0,44,1));r.addView(presetRow);ListView list=new ListView(this);adapter=new ArrayAdapter<ProxyEvent>(this,android.R.layout.simple_list_item_2,android.R.id.text1,items){@Override public View getView(int p,View c,ViewGroup g){View v=super.getView(p,c,g);ProxyEvent e=getItem(p);((TextView)v.findViewById(android.R.id.text1)).setText(e.toString());((TextView)v.findViewById(android.R.id.text2)).setText(detail(e));return v;}};list.setAdapter(adapter);list.setOnItemClickListener((a,v,p,id)->show(items.get(p)));r.addView(list,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bot=new LinearLayout(this);Button dash=new Button(this);dash.setText("DASHBOARD");dash.setOnClickListener(v->startActivity(new Intent(this,DashboardActivity.class)));bot.addView(dash,new LinearLayout.LayoutParams(0,48,1));Button export=new Button(this);export.setText("EXPORT");export.setOnClickListener(v->exportHistory());bot.addView(export,new LinearLayout.LayoutParams(0,48,1));Button clear=new Button(this);clear.setText("CLEAR");clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Clear proxy history?").setPositiveButton("CLEAR",(d,w)->{ProxyHistoryRepository.clear();refresh();}).setNegativeButton("CANCEL",null).show());bot.addView(clear,new LinearLayout.LayoutParams(0,48,1));r.addView(bot);return r;}

 private void exportHistory(){try{java.io.File f=ExportManager.writeText(this,"reqlens-proxy-"+System.currentTimeMillis()+".json",HistoryExporter.proxyJson(ProxyHistoryRepository.snapshotActiveProject()));startActivity(Intent.createChooser(ExportManager.share(this,f,"application/json"),"Export proxy history"));}catch(Exception e){Toast.makeText(this,"Export failed: "+e.getMessage(),Toast.LENGTH_SHORT).show();}}

 private void saveFilterPreset(){getSharedPreferences("reqlens_proxy_filter",MODE_PRIVATE).edit().putString("q",filter.getText().toString()).putInt("source",source.getSelectedItemPosition()).putInt("status",status.getSelectedItemPosition()).apply();Toast.makeText(this,"Filter preset saved",Toast.LENGTH_SHORT).show();}
 private void loadFilterPreset(){android.content.SharedPreferences p=getSharedPreferences("reqlens_proxy_filter",MODE_PRIVATE);filter.setText(p.getString("q",""));source.setSelection(p.getInt("source",0));status.setSelection(p.getInt("status",0));refresh();}
 private AdapterView.OnItemSelectedListener sel(){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>p,View v,int x,long id){refresh();}public void onNothingSelected(AdapterView<?>p){}};}
 private void refresh(){String q=filter==null?"":filter.getText().toString().trim().toLowerCase(Locale.ROOT);String src=source==null?"ALL SOURCES":String.valueOf(source.getSelectedItem());String st=status==null?"ALL STATUS":String.valueOf(status.getSelectedItem());items.clear();HashSet<String>hosts=new HashSet<>();long bytes=0;for(ProxyEvent e:ProxyHistoryRepository.snapshotActiveProject()){String hay=(e.source+" "+e.protocol+" "+e.host+" "+e.ip+" "+e.appLabel+" "+e.appPackage+" "+e.method+" "+e.url+" "+e.tlsSni).toLowerCase(Locale.ROOT);if(!q.isEmpty()&&!hay.contains(q))continue;if(!"ALL SOURCES".equals(src)&&!src.equalsIgnoreCase(e.source))continue;if(!statusMatch(st,e.status))continue;items.add(e);if(!e.host.isEmpty())hosts.add(e.host);bytes+=Math.max(0,e.bytes);}if(adapter!=null)adapter.notifyDataSetChanged();if(summary!=null)summary.setText(items.size()+" events • "+hosts.size()+" hosts • "+bytes+" observed bytes");}
 private boolean statusMatch(String f,int s){if("ALL STATUS".equals(f))return true;if("ERROR".equals(f))return s<0;return s>=Integer.parseInt(f.substring(0,1))*100&&s<Integer.parseInt(f.substring(0,1))*100+100;}
 private String detail(ProxyEvent e){String tls=e.tlsSni.isEmpty()?"":" • SNI "+e.tlsSni+(e.tlsAlpn.isEmpty()?"":" • "+e.tlsAlpn);return e.source+" • "+(e.status>=0?"HTTP "+e.status+" • ":"")+e.bytes+" B"+tls;}
 private void show(ProxyEvent e){String m="Source: "+e.source+"\nProtocol: "+e.protocol+"\nHost: "+e.host+"\nIP: "+e.ip+":"+e.port+"\nApp: "+e.appLabel+"\nPackage: "+e.appPackage+"\nTLS SNI: "+e.tlsSni+"\nALPN: "+e.tlsAlpn+"\nTLS: "+e.tlsVersion+"\nBytes: "+e.bytes+(e.url.isEmpty()?"":"\nURL: "+e.url);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("Proxy event").setMessage(m).setNegativeButton("CLOSE",null);if(!e.url.isEmpty())b.setPositiveButton("REPEATER",(d,w)->{RequestRecord q=new RequestRecord();q.method=e.method.isEmpty()?"GET":e.method;q.url=e.url;RepeaterActivity.pending=q;startActivity(new Intent(this,RepeaterActivity.class));});b.show();}
}
